#!/usr/bin/env node
// Bundles SKILL.md files from Agent-zero-pentest into data/skills.js.
// Preserves existing metadata (name, category, tags, description) and populates body.
//
// The sources are written for Agent Zero, which runs skills inside a container and
// exposes a `code_execution_tool` plus scripts under /a0/. Void has neither. Copied
// verbatim, those sections instruct the model to call a tool that does not exist —
// a guaranteed hallucinated call and a wasted turn every time the skill loads. So
// the bodies are sanitised on the way in; see sanitizeBody below.
//
// Usage: node scripts/bundle-skills.js [path-to-Agent-zero-pentest]
const fs = require('fs');
const path = require('path');

const SKILLS_SUBPATH = 'patches/plugins/_pentest_kit/skills';
const repoArg = process.argv[2];
const srcDir = repoArg
  ? path.join(repoArg, SKILLS_SUBPATH)
  : 'C:/Users/jaime/Agent-zero-pentest/' + SKILLS_SUBPATH;
const skillsFile = path.join(__dirname, '..', 'data', 'skills.js');

if (!fs.existsSync(srcDir)) {
  console.error('No skills directory at ' + srcDir);
  console.error('Usage: node scripts/bundle-skills.js <path-to-Agent-zero-pentest>');
  process.exit(1);
}

// Strip everything that tells the model to use tooling Void does not have, and
// replace it with the Void equivalent rather than leaving a hole.
function sanitizeBody(body, slug) {
  const before = body;
  let out = body;

  // 1. Fenced blocks whose content is an Agent Zero tool call.
  out = out.replace(/```[a-z]*\n(?:(?!```)[\s\S])*?code_execution_tool(?:(?!```)[\s\S])*?```\n?/g, '');

  // 2. Inline references to the container's script paths.
  out = out.replace(/`?\/a0\/[^\s`)"']*`?/g, 'the equivalent Void tool');

  // 3. Any surviving mention of the tool name itself.
  out = out.replace(/`?code_execution_tool`?/g, 'the Void tools');

  // 4. Headings left with nothing under them once their blocks went.
  out = out.replace(/^#{2,4} +(?:Example Commands[^\n]*|Automation Scripts[^\n]*)\n+(?=#{1,4} |$)/gm, '');

  // 5. Collapse the blank runs the removals leave behind.
  out = out.replace(/\n{4,}/g, '\n\n\n').trim();

  if (out !== before) {
    const note = '\n\n## Tooling note\n\n' +
      'This methodology came from a container-based agent. In Void you drive it with the ' +
      'panel tools instead: `send_request` for individual probes, `run_intruder_attack` for ' +
      'payload sweeps, `run_hybrid_scan` for the deterministic checks, `compare_responses` ' +
      'for baseline diffing, and `add_pentest_finding` to record a confirmed result. ' +
      'There is no shell and no filesystem — do not attempt to run scripts.';
    out += note;
    console.log('       sanitised Agent Zero tool references in ' + slug);
  }
  return out;
}

const vm = require('vm');
const sandbox = { window: {} };
vm.createContext(sandbox);
vm.runInContext(fs.readFileSync(skillsFile, 'utf8'), sandbox);
const existingSkills = sandbox.window.VOID_SKILLS || {};

// Methodologies written for Void rather than inherited from upstream. They take
// precedence, so a skill whose upstream SKILL.md is missing or empty still ships a
// real body — file-upload was shipping nothing at all.
const localDir = path.join(__dirname, '..', 'skills-local');

const dirs = fs.readdirSync(srcDir).filter(d => fs.statSync(path.join(srcDir, d)).isDirectory());
if (fs.existsSync(localDir)) {
  for (const d of fs.readdirSync(localDir)) if (!dirs.includes(d)) dirs.push(d);
}

let updated = 0, empty = [];
for (const slug of dirs) {
  const localPath = path.join(localDir, slug, 'SKILL.md');
  const mdPath = fs.existsSync(localPath) ? localPath : path.join(srcDir, slug, 'SKILL.md');
  if (fs.existsSync(localPath)) console.log('       using local body for ' + slug);
  if (!fs.existsSync(mdPath)) { console.log('  SKIP ' + slug + ' (no SKILL.md)'); continue; }
  const raw = fs.readFileSync(mdPath, 'utf8').trim();
  if (!existingSkills[slug]) { console.log('  NEW  ' + slug + ' (not in existing skills.js — skipped)'); continue; }
  if (!raw) { empty.push(slug); console.log('  WARN ' + slug + ' (source SKILL.md is empty — keeping existing body)'); continue; }
  existingSkills[slug].body = sanitizeBody(raw, slug);
  updated++;
  console.log('  OK   ' + slug + ' (' + existingSkills[slug].body.split('\n').length + ' lines)');
}

// A shipped skill with no body injects nothing but its one-line description, which
// is worse than useless: the model believes it loaded a methodology.
const stillEmpty = Object.entries(existingSkills).filter(([, v]) => !(v.body || '').trim()).map(([k]) => k);
if (stillEmpty.length) console.log('\n  EMPTY BODIES (skill loads but injects no methodology): ' + stillEmpty.join(', '));

let out = '// data/skills.js \u2014 ' + Object.keys(existingSkills).length + ' pentesting skill methodologies\n';
out += '// Bodies from Agent-zero-pentest SKILL.md files, sanitised for Void tooling.\n';
out += '// Generated by scripts/bundle-skills.js \u2014 do not edit by hand.\n';
out += '// User edits belong in the panel (AI Settings \u2192 Skills), stored as an overlay.\n\n';
out += 'window.VOID_SKILLS = ' + JSON.stringify(existingSkills, null, 2) + ';\n';
fs.writeFileSync(skillsFile, out, 'utf8');

console.log('\nWritten to ' + skillsFile);
console.log('Updated: ' + updated + ' skills');
console.log('File size: ' + (fs.statSync(skillsFile).size / 1024).toFixed(0) + ' KB');
